package org.codex.nfsugpreview;
import android.app.*;import android.os.*;import java.io.*;import java.nio.*;import java.nio.file.*;import org.json.*;
public final class SplitSceneGpuInstrumentation extends SceneGpuInstrumentation {
 NativeSceneDrawPlan[] owners;float[][][] sources;int[][][] shades;int cachedWidth=-1;int[] visible={0,0};boolean sentinel;int[][] colors;int rowChecks;int[] exactRows={0,0};
 @Override int[] expected(NativeSceneSnapshot scene,NativeSceneDrawPlan ignored,float[][] unused,double x,double y){if(cachedWidth!=testViewportWidth){shades=new int[2][][];for(int owner=0;owner<2;owner++){shades[owner]=new int[owners[owner].count()][];for(int di=0;di<owners[owner].count();di++)if(owners[owner].draw(di).lighting!=null&&owners[owner].draw(di).lighting.curve!=null)shades[owner][di]=owners[owner].draw(di).lighting.curve.columns(testViewportWidth);}cachedWidth=testViewportWidth;}int owner=y<scene.splitRow?0:1;shadeColumns=shades[owner];lastSample="";int[] value=super.expected(scene,owners[owner],sources[owner],x,y);if(value!=null&&!lastSample.isEmpty())visible[owner]++;return value;}
 @Override void afterReadback(NativeSceneSnapshot scene,int width,int height,int activeWidth,int activeHeight,ByteBuffer pixels){if(!sentinel)return;int x=Math.max(0,activeWidth/24);for(int y=0;y<activeHeight;y++){double source=(activeHeight-y-.5)*160/activeHeight;int owner=source<scene.splitRow?0:1,at=(y*width+x)*4;for(int c=0;c<3;c++)ok((pixels.get(at+c)&255)==colors[owner][c],"Owner row gap/overlap cut="+scene.splitRow+" y="+y);rowChecks++;exactRows[owner]++;}}
 @Override public void onStart(){Bundle result=new Bundle();boolean live=false;try{NativeSceneSnapshot scene=new NativeSceneSnapshot(Files.readAllBytes(new File(getTargetContext().getFilesDir(),"split-scene.nab").toPath()));ok(scene.kind==2,"Recorded split required");owners=new NativeSceneDrawPlan[2];sources=new float[2][][];colors=new int[2][3];sentinel=true;for(int owner=0;owner<2;owner++){owners[owner]=new NativeSceneDrawPlan(scene.geometry(owner));sources[owner]=new float[owners[owner].count()][];for(int di=0;di<owners[owner].count();di++){FloatBuffer vertices=owners[owner].draw(di).mesh();sources[owner][di]=new float[vertices.remaining()];vertices.get(sources[owner][di]);}NativeWorldScene world=new NativeWorldScene(scene.geometry(owner));ByteBuffer image=world.surface(0).texture();for(int c=0;c<3;c++)colors[owner][c]=image.get(c)&255;sentinel&=world.surfaceCount()==1&&colors[owner][0]==(owner==0?211:17)&&colors[owner][1]==(owner==0?37:61)&&colors[owner][2]==(owner==0?19:227);}
 startGl();live=true;String small=render(scene,240,160,240,160,"split-scene-240.png",false),large=render(scene,3840,2160,3240,2160,"split-scene-4k.png",false);endGl();live=false;startGl();live=true;ok(render(scene,240,160,240,160,null,false).equals(small),"Split context changed pixels");ok(sentinel?(exactRows[0]>0&&exactRows[1]>0):(visible[0]>0&&visible[1]>0),"Both owners must be verified");if(sentinel)ok(rowChecks>=2480,"Every sentinel row must be checked");JSONObject report=new JSONObject();report.put("result","PASS_ANDROID_SPLIT_SCENE_GLES");report.put("split_row",scene.splitRow);report.put("source_pixel_checks",checks);report.put("owner0_visible_sample_evaluations",visible[0]);report.put("owner1_visible_sample_evaluations",visible[1]);report.put("synthetic_sentinel",sentinel);report.put("exact_owner_row_checks",rowChecks);report.put("owner0_exact_rows",exactRows[0]);report.put("owner1_exact_rows",exactRows[1]);report.put("native_rgba_sha256",small);report.put("four_k_frame_sha256",large);report.put("context_recreated",true);report.put("api",Build.VERSION.SDK_INT);report.put("renderer",renderer);report.put("real_time_pacing",false);report.put("full_scene",false);try(FileOutputStream out=getTargetContext().openFileOutput("split-scene-report.json",0)){out.write(report.toString(2).getBytes("UTF-8"));}result.putString("stream",report.toString());finish(Activity.RESULT_OK,result);}catch(Throwable e){android.util.Log.e("NFSUGSceneGPU","Failed",e);result.putString("stream","FAIL: "+e);finish(Activity.RESULT_CANCELED,result);}finally{if(live)endGl();}}
}
